import heapq

def merge_sorted_streams(*streams):
    streams = list(streams)
    streams = [stream for stream in streams if stream]  # Remove empty streams
    iterators = [iter(stream) for stream in streams]
    heap = []

    for i, iterator in enumerate(iterators):
        try:
            key, value = next(iterator)
            heap.append((key, i, value, iterator))
        except StopIteration:
            pass

    heapq.heapify(heap)

    while heap:
        key, index, value, iterator = heap[0]
        try:
            new_key, new_value = next(iterator)
            if new_key == key:
                heap[0] = (new_key, index, new_value, iterator)
            else:
                yield key, value
                heap[0] = (new_key, index, new_value, iterator)
        except StopIteration:
            yield key, value
            heapq.heappop(heap)

        heapq.heapify(heap)
